// node work/persian/htmlfilm/lib/shaders/build.mjs
// Writes the native shaders (transitions/*.glsl, effects/*.glsl) with their header comments, prepends a header to the vendored gl-transitions
// files (MIT, https://github.com/gl-transitions/gl-transitions), and generates shaders/index.js (registers every shader in PA.fx).
// The catalogue (docs/motion/fx/catalog.json) is generated by work/persian/htmlfilm/lib/fx-lab.mjs from META below + the verification results.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
const HERE = path.dirname(fileURLToPath(import.meta.url));
const TD = path.join(HERE, 'transitions'), ED = path.join(HERE, 'effects');
const NOISE = `float hash21(vec2 p) { p = fract(p * vec2(123.34, 456.21) + seed * 0.0137); p += dot(p, p + 45.32); return fract(p.x * p.y); }
float vnoise(vec2 p) { vec2 i = floor(p), f = fract(p); f = f * f * (3.0 - 2.0 * f);
  return mix(mix(hash21(i), hash21(i + vec2(1, 0)), f.x), mix(hash21(i + vec2(0, 1)), hash21(i + vec2(1, 1)), f.x), f.y); }
float fbm(vec2 p) { float a = 0.5, s = 0.0; for (int i = 0; i < 4; i++) { s += a * vnoise(p); p *= 2.02; a *= 0.5; } return s; }
`;
const NATIVE_T = {
  'wipe-left': ['wipe', 'Hard-edged wipe from right to left with a soft edge.', 'softness', `uniform float softness; // = 0.04
vec4 transition(vec2 uv) { float e = 1.0 - progress; float m = smoothstep(e - softness, e + softness, uv.x * (1.0 - softness * 2.0) + softness); return mix(getFromColor(uv), getToColor(uv), m); }`],
  'swirl': ['warp', 'Both images twist around the centre while crossfading (stronger at mid-transition).', 'strength', `uniform float strength; // = 6.0
vec4 transition(vec2 uv) { vec2 c = uv - 0.5; c.x *= ratio; float r = length(c); float a = strength * sin(progress * 3.14159) * (1.0 - smoothstep(0.0, 0.9, r));
  float s = sin(a), co = cos(a); vec2 q = vec2(co * c.x - s * c.y, s * c.x + co * c.y); q.x /= ratio; q += 0.5; return mix(getFromColor(q), getToColor(q), smoothstep(0.35, 0.65, progress)); }`],
  'noise-dissolve': ['dissolve', 'Organic noise dissolve: the new image grows through fractal noise blobs with a soft edge (seeded, deterministic).', 'scale, softness', `${NOISE}uniform float scale; // = 5.0
uniform float softness; // = 0.12
vec4 transition(vec2 uv) { float n = fbm(uv * vec2(ratio, 1.0) * scale); float p = progress * (1.0 + softness * 2.0) - softness; float m = smoothstep(p - softness, p + softness, n); return mix(getToColor(uv), getFromColor(uv), m); }`],
  'luma-wipe': ['wipe', 'Luma/diagonal wipe driven by a procedural gradient + noise map (no texture needed).', 'angle, softness', `${NOISE}uniform float angle; // = 0.6
uniform float softness; // = 0.15
vec4 transition(vec2 uv) { vec2 d = vec2(cos(angle), sin(angle)); float l = dot(uv - 0.5, d) + 0.5 + (vnoise(uv * 6.0) - 0.5) * 0.12; float p = progress * (1.0 + softness * 2.0) - softness; float m = smoothstep(p - softness, p + softness, l); return mix(getToColor(uv), getFromColor(uv), m); }`],
  'page-curl-lite': ['fold', 'Page-turn approximation: a fold line sweeps right to left; the old page shows its darker back mirrored along the fold, the new image lies beneath.', 'radius', `uniform float radius; // = 0.16
vec4 transition(vec2 uv) { float e = 1.0 - progress * (1.0 + radius); float x = uv.x - e;
  if (x < 0.0) return getFromColor(uv);
  if (x < radius) { float k = x / radius; vec4 back = getFromColor(vec2(e - x, uv.y)); return vec4(back.rgb * (0.55 + 0.35 * k), 1.0); }
  return getToColor(uv); }`],
  'circle-reveal': ['reveal', 'A circle opens from the centre revealing the new image with a soft rim.', 'softness', `uniform float softness; // = 0.03
vec4 transition(vec2 uv) { vec2 c = uv - 0.5; c.x *= ratio; float r = length(c); float R = progress * (0.5 * length(vec2(ratio, 1.0)) + softness); float m = smoothstep(R, R - softness, r); return mix(getFromColor(uv), getToColor(uv), m); }`],
  'displace-dissolve': ['dissolve', 'Both images are pushed apart by a noise displacement field while crossfading (liquid shimmer).', 'strength, scale', `${NOISE}uniform float strength; // = 0.08
uniform float scale; // = 4.0
vec4 transition(vec2 uv) { vec2 n = vec2(fbm(uv * scale + 3.1), fbm(uv * scale + 9.7)) - 0.5; float k = sin(progress * 3.14159) * strength; vec2 q = n * k * 2.0; return mix(getFromColor(uv + q), getToColor(uv - q), smoothstep(0.2, 0.8, progress)); }`],
};
const NATIVE_E = {
  'ripple-wave': ['distortion', 'Concentric ripples radiate from the centre, damping with t.', 'amplitude, frequency', `uniform float amplitude; // = 0.02
uniform float frequency; // = 24.0
effect_placeholder`, `vec4 effect(vec2 uv) { vec2 c = uv - 0.5; c.x *= ratio; float r = length(c); float k = sin(r * frequency - t * 12.0) * amplitude * (1.0 - t) ; vec2 dir = r > 0.0001 ? normalize(c) : vec2(0.0); vec2 q = uv + dir * k * vec2(1.0 / ratio, 1.0); return getColor(q); }`],
  'swirl-vortex': ['distortion', 'Vortex twist around the centre that unwinds as t goes 0 to 1 (t=0 twisted, t=1 clean).', 'strength', `uniform float strength; // = 7.0
effect_placeholder`, `vec4 effect(vec2 uv) { vec2 c = uv - 0.5; c.x *= ratio; float r = length(c); float a = strength * (1.0 - t) * (1.0 - smoothstep(0.0, 0.8, r)); float s = sin(a), co = cos(a); vec2 q = vec2(co * c.x - s * c.y, s * c.x + co * c.y); q.x /= ratio; return getColor(q + 0.5); }`],
  'rgb-glitch': ['glitch', 'RGB channel split plus horizontal scanline displacement bands; intensity peaks mid t (seeded).', 'amount, bands', `uniform float amount; // = 0.02
uniform float bands; // = 24.0
effect_placeholder`, `${NOISE}vec4 effect(vec2 uv) { float k = sin(t * 3.14159); float row = floor(uv.y * bands); float off = (hash21(vec2(row, floor(t * 10.0))) - 0.5) * amount * 4.0 * k * step(0.7, hash21(vec2(row + 7.0, floor(t * 10.0))));
  vec2 u = uv + vec2(off, 0.0); float sp = amount * k; vec4 c = vec4(getColor(u + vec2(sp, 0.0)).r, getColor(u).g, getColor(u - vec2(sp, 0.0)).b, 1.0); c.rgb *= 1.0 - 0.08 * k * step(0.5, fract(uv.y * resolution.y * 0.5)); return c; }`],
  'pixel-dissolve': ['dissolve', 'Image breaks into blocks that turn to the background colour in random order (t 0 clean to 1 gone).', 'block, bg', `uniform float block; // = 48.0
uniform vec3 bg; // = vec3(0.05, 0.05, 0.08)
effect_placeholder`, `${NOISE}vec4 effect(vec2 uv) { vec2 g = floor(uv * vec2(block * ratio, block)); float r = hash21(g); float m = step(r, t * 1.15 - 0.075); vec4 c = getColor((g + 0.5) / vec2(block * ratio, block)); return mix(getColor(uv), vec4(bg, 1.0), m) * 1.0 + c * 0.0; }`],
  'noise-displace': ['distortion', 'Heat-haze noise displacement that fades out with t.', 'strength, scale', `uniform float strength; // = 0.05
uniform float scale; // = 6.0
effect_placeholder`, `${NOISE}vec4 effect(vec2 uv) { vec2 n = vec2(fbm(uv * scale + t * 2.0), fbm(uv * scale + 5.2 - t * 2.0)) - 0.5; return getColor(uv + n * strength * (1.0 - t)); }`],
  'crumple-fold': ['fold', 'Crumple-ish approximation: faceted fold lines displace and shade the image (paper look), relaxing as t goes 0 to 1.', 'facets, depth', `uniform float facets; // = 5.0
uniform float depth; // = 0.06
effect_placeholder`, `${NOISE}vec4 effect(vec2 uv) { vec2 g = uv * facets; vec2 id = floor(g); vec2 f = fract(g); float h = hash21(id); float h2 = hash21(id + 17.0); vec2 dir = vec2(h - 0.5, h2 - 0.5);
  float k = (1.0 - t); vec2 q = uv + dir * depth * k * (0.5 + f.x * f.y); float shade = 1.0 - (0.25 * (h - 0.5) + 0.1 * (f.x - 0.5)) * k; vec4 c = getColor(q); return vec4(c.rgb * shade, 1.0); }`],
};
const META = { // family/description for the vendored gl-transitions (what it looks like)
  fade: ['fade', 'Plain crossfade.'], fadecolor: ['fade', 'Fades through a flat colour (default black).'], fadegrayscale: ['fade', 'Fades through grayscale.'],
  directionalwipe: ['wipe', 'Soft directional wipe along a direction vector.'], ripple: ['warp', 'Ripples spread from the centre while crossfading.'], pixelize: ['pixel', 'Both images pixelate then resolve into the new one.'],
  circleopen: ['reveal', 'Circle opens/closes revealing the new image.'], crosswarp: ['warp', 'Cross warp: images stretch into each other.'], CrossZoom: ['zoom', 'Zoom blur burst between the images.'], Radial: ['reveal', 'Radial clock-style sweep reveals the new image.'],
  GlitchDisplace: ['glitch', 'Horizontal slice displacement glitch.'], GlitchMemories: ['glitch', 'Glitchy RGB split memories.'], windowslice: ['wipe', 'Venetian-blind slices slide in.'], cube: ['3d', 'Rotating cube between the images (pseudo 3D).'],
  Dreamy: ['warp', 'Dreamy wavy crossfade.'], LinearBlur: ['blur', 'Directional blur crossfade.'], squareswire: ['grid', 'Square grid wire sweep.'], morph: ['warp', 'Colour-driven morph displacement.'],
  undulatingBurnOut: ['burn', 'Burn-out style undulating radial wipe.'], hexagonalize: ['pixel', 'Hexagon mosaic transition.'], StereoViewer: ['3d', 'Stereo-viewer style zoom frame.'], SimpleZoom: ['zoom', 'Zoom into the old image, out of the new.'], BowTieHorizontal: ['wipe', 'Bow-tie shaped horizontal wipe.'],
};
fs.mkdirSync(TD, { recursive: true }); fs.mkdirSync(ED, { recursive: true });
for (const f of fs.readdirSync(TD)) { const p = path.join(TD, f); if (fs.statSync(p).size < 50) fs.rmSync(p); } // failed downloads (404 bodies)
const out = { transitions: {}, effects: {} };
for (const [n, [fam, desc, params, body]] of Object.entries(NATIVE_T)) {
  fs.writeFileSync(path.join(TD, n + '.glsl'), `// name: ${n}\n// family: ${fam}\n// behaviour: ${desc}\n// params: ${params}\n// source: native (persian-arts), MIT-compatible, written for pa-fx\n${body}\n`);
}
for (const [n, [fam, desc, params, pre, body]] of Object.entries(NATIVE_E)) {
  fs.writeFileSync(path.join(ED, n + '.glsl'), `// name: ${n}\n// family: ${fam}\n// behaviour: ${desc}\n// params: ${params}\n// source: native (persian-arts)\n${pre.replace('effect_placeholder', '')}\n${body}\n`);
}
for (const f of fs.readdirSync(TD)) {
  const n = f.replace('.glsl', ''); const p = path.join(TD, f); let s = fs.readFileSync(p, 'utf8');
  if (!/^\/\/ name:/m.test(s)) { const m = META[n] || ['misc', n]; s = `// name: ${n}\n// family: ${m[0]}\n// behaviour: ${m[1]}\n// source: gl-transitions catalogue (MIT), https://github.com/gl-transitions/gl-transitions/blob/master/transitions/${f} (author/licence lines below are the originals)\n` + s; fs.writeFileSync(p, s); }
  out.transitions[n] = s;
}
for (const f of fs.readdirSync(ED)) out.effects[f.replace('.glsl', '')] = fs.readFileSync(path.join(ED, f), 'utf8');
const idx = `/* GENERATED by lib/shaders/build.mjs: registers every shader into PA.fx (gl-transitions MIT + native). Do not edit. */\n(function () {\n  const R = PA.fx.register;\n` +
  Object.entries(out.transitions).map(([n, s]) => `  R(${JSON.stringify(n)}, ${JSON.stringify(s)}, "transition");`).join('\n') + '\n' +
  Object.entries(out.effects).map(([n, s]) => `  R(${JSON.stringify(n)}, ${JSON.stringify(s)}, "effect");`).join('\n') + '\n})();\n';
fs.writeFileSync(path.join(HERE, 'index.js'), idx);
fs.writeFileSync(path.join(HERE, 'LICENSE-gl-transitions.txt'), 'Vendored shader files under transitions/ that carry "License: MIT" headers come from https://github.com/gl-transitions/gl-transitions (MIT License, copyright the gl-transitions authors and the individual shader authors named in each file). Native shaders are ours.\n');
console.log('transitions', Object.keys(out.transitions).length, 'effects', Object.keys(out.effects).length);
